  (11, 'MarsGate', 'Země se ocitla na pokraji ekologického kolapsu a společnost se potácí v nejistotě. ', true, 15, 'categories/t0qc2g4l.eio.png'),
  (12, 'Připravujeme pro vás', 'aktuálně si zahrajte příběh MarsGate!', true, 1, 'categories/3kne2fjx.zfo.webp');
insert into public.fun_facts (id, category_id, title, text) values
  (12, 11, 'Do roku 2020 měla na Facebooku reakce “to mě štve” v algoritmech až pětkrát vyšší hodnotu než like.', 'Merrill, Jeremy B., and Will Oremus. 2023. “Five Points for Anger, One for a ‘Like’: How Facebook’s Formula Fostered Rage and Misinformation.” The Washington Post, November 27, 2023. https://www.washingtonpost.com/technology/2021/10/26/facebook-angry-emoji-algorithm/.'),
  (14, 11, 'Zatímco smutek v nás vzbuzuje bezmoc, vztek nás motivuje k akci, jako je komentování či sdílení příspěvku který nemusí být pravdivý.', 'Horner, Christy Galletta, Dennis Galletta, Jennifer Crawford, and Abhijeet Shirsat. 2021. ''Emotions: The Unexplored Fuel of Fake News on Social Media.'' Journal of Management Information Systems 38 (4): 1039–66. https://doi.org/10.1080/07421222.2021.1990610.'),
  (15, 11, 'Pokud v nás nějaká informace vzbudí vztek, je vyšší šance, že se utvrdíme v našich předchozích názorech.', 'Lühring, Jula, Apeksha Shetty, Corinna Koschmieder, David Garcia, Annie Waldherr, and Hannah Metzler. 2024. “Emotions in Misinformation Studies: Distinguishing Affective State From Emotional Response and Misinformation Recognition From Acceptance.” Cognitive Research Principles and Implications 9 (1). https://doi.org/10.1186/s41235-024-00607-0.'),
  (16, 11, 'Pokud v nás příspěvek vyvolá jakékoli silné emoce, ať už pozitivní nebo negativní, je větší šance, že ho budeme sdílet.', 'Thompson, Rj. 2022. “How Emotions Fuel Fake News on Social Media.” Pitt Business. November 30, 2022. https://business.pitt.edu/how-emotions-fuel-fake-news-on-social-media/.'),
  (17, 11, 'Politické zprávy jsou nejvirálnější skupinou falešných zpráv. Šíří se až 3x rychleji než jakákoliv jiná kategorie falešných informací.', 'Vosoughi, S., Roy, D., & Aral, S. (2018). The spread of true and false news online. Science, 359(6380), 1146–1151. https://doi.org/10.1126/science.aap9559'),
  (18, 11, 'Nepravdivé zprávy mají o 70 % větší šanci, že je někdo přesdílí, než ty pravdivé – i když je často šíří účty s méně sledujícími a nižší aktivitou.', 'Vosoughi, S., Roy, D., & Aral, S. (2018). The spread of true and false news online. Science, 359(6380), 1146–1151. https://doi.org/10.1126/science.aap9559 '),
  (19, 11, 'Falešné zprávy častěji vyvolávají reakce překvapení a znechucení, zatímco na pravdivé informace lidé reagují spíš smutkem, očekáváním, radostí nebo důvěrou.', 'Vosoughi, S., Roy, D., & Aral, S. (2018). The spread of true and false news online. Science, 359(6380), 1146–1151. https://doi.org/10.1126/science.aap9559 ');
